class GroupByLength {
    Map<Integer, List<String>> group(List<String> words) {
        Map<Integer, List<String>> groups = new HashMap<>();
        int longest = 0;
        for (String word : words) {
            List<String> bucket = groups.get(word.length());
            if (bucket == null) {
                bucket = new ArrayList<>();
                groups.put(word.length(), bucket);
            }
            bucket.add(word);
            longest = Math.max(longest, word.length());
        }
        int distinct = groups.size();
        System.out.println(distinct + " " + longest);
        return groups;
    }
}

import java.util.Map;
import java.util.TreeMap;

class CountTokensMerge {
    Map<String, Integer> countTokens(String text) {
        Map<String, Integer> counts = new TreeMap<>();
        String[] tokens = text.toLowerCase().split(",");
        for (String token : tokens) {
            counts.merge(token.trim(), 1, Integer::sum);
        }
        counts.remove("");
        int distinct = counts.size();
        System.out.println(distinct);
        return counts;
    }
}

