class JoinWithCommas {
    String join(List<String> items) {
        StringBuilder sb = new StringBuilder();
        int index = 0;
        for (String item : items) {
            if (index > 0) {
                sb.append(", ");
            }
            sb.append(item);
            index++;
        }
        sb.append(".");
        String result = sb.toString();
        return result;
    }
}

import java.util.List;

class JoinReversed {
    String joinReversed(List<String> items) {
        StringBuilder sb = new StringBuilder();
        int index = items.size() - 1;
        while (index >= 0) {
            sb.append(items.get(index));
            if (index > 0) {
                sb.append(", ");
            }
            index--;
        }
        sb.append(".");
        String result = sb.toString();
        return result;
    }
}

class BuildCsvRow {
    String csvRow(String[] cells) {
        StringBuilder sb = new StringBuilder();
        int index = 0;
        for (String cell : cells) {
            if (index > 0) {
                sb.append(',');
            }
            sb.append('"').append(cell.replace("\"", "\"\"")).append('"');
            index++;
        }
        sb.append("\n");
        String result = sb.toString();
        return result;
    }
}

class RepeatString {
    String repeat(String unit, int times, String separator) {
        StringBuilder sb = new StringBuilder();
        int index = 0;
        while (index < times) {
            if (index > 0) {
                sb.append(separator);
            }
            sb.append(unit);
            index++;
        }
        sb.append("!");
        String result = sb.toString();
        return result;
    }
}

