class ArraySumAverage {
    double average(int[] values) {
        if (values.length == 0) {
            return 0.0;
        }
        long sum = 0;
        for (int i = 0; i < values.length; i++) {
            sum += values[i];
        }
        double avg = (double) sum / values.length;
        System.out.println(sum);
        return avg;
    }
}

class ArrayMinMax {
    int range(int[] values) {
        if (values.length == 0) {
            return 0;
        }
        int min = values[0];
        int max = values[0];
        for (int i = 1; i < values.length; i++) {
            min = Math.min(min, values[i]);
            max = Math.max(max, values[i]);
        }
        int range = max - min;
        System.out.println(min + " " + max);
        return range;
    }
}

class ArrayVariance {
    double variance(double[] values) {
        if (values.length == 0) {
            return 0.0;
        }
        double sum = 0;
        for (int i = 0; i < values.length; i++) {
            sum += values[i];
        }
        double mean = sum / values.length;
        double squares = 0;
        for (int i = 0; i < values.length; i++) {
            squares += (values[i] - mean) * (values[i] - mean);
        }
        double result = squares / values.length;
        return result;
    }
}

class ArrayCountAbove {
    int countAbove(int[] values, int threshold) {
        if (values.length == 0) {
            return 0;
        }
        int count = 0;
        for (int i = 0; i < values.length; i++) {
            if (values[i] > threshold) {
                count++;
            }
        }
        double ratio = (double) count / values.length;
        System.out.println(ratio);
        return count;
    }
}

class ParseIntDefault {
    int parseOrDefault(String text, int fallback) {
        if (text == null) {
            return fallback;
        }
        String trimmed = text.trim();
        int value = fallback;
        try {
            value = Integer.parseInt(trimmed);
        } catch (NumberFormatException e) {
            System.err.println("bad number: " + trimmed);
        }
        System.out.println(value);
        return value;
    }
}

