class ParsePort {
    int parsePort(String text) {
        if (text == null) {
            return 80;
        }
        String trimmed = text.trim();
        int port = 80;
        try {
            port = Integer.parseInt(trimmed);
        } catch (NumberFormatException e) {
            System.err.println("bad port: " + trimmed);
        }
        if (port < 1 || port > 65535) {
            port = 80;
        }
        return port;
    }
}

class ParseLongTimeout {
    long parseTimeout(String text, long fallback) {
        if (text == null) {
            return fallback;
        }
        String trimmed = text.trim().toLowerCase();
        long millis = fallback;
        try {
            millis = Long.parseLong(trimmed.replace("ms", ""));
        } catch (NumberFormatException e) {
            System.err.println("bad timeout: " + trimmed);
        }
        System.out.println(millis);
        return millis;
    }
}

