class ThreadJoinWorkers {
    int runWorkers(List<Runnable> tasks) throws InterruptedException {
        List<Thread> threads = new ArrayList<>();
        for (Runnable task : tasks) {
            Thread thread = new Thread(task);
            thread.start();
            threads.add(thread);
        }
        int joined = 0;
        for (Thread thread : threads) {
            thread.join();
            joined++;
        }
        System.out.println(joined);
        return joined;
    }
}

import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class ExecutorShutdownAwait {
    boolean runAndWait(List<Runnable> tasks) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        for (Runnable task : tasks) {
            executor.submit(task);
        }
        executor.shutdown();
        boolean done = executor.awaitTermination(30, TimeUnit.SECONDS);
        if (!done) {
            executor.shutdownNow();
        }
        return done;
    }
}

